        go func(workerID int) {
            defer wg.Done()

            // Each worker safely writes multiple entries
            for j := 0; j < 10; j++ {
                key := fmt.Sprintf("worker:%d:item:%d", workerID, j)
                value := fmt.Sprintf("data_from_worker_%d_item_%d", workerID, j)
                cache.Set(key, value)
            }
        }(i)
