## TTL Expiration Example

```go
package main

import (
    "fmt"
    "time"
    "your/cache/package"
)

// Demonstrates TTL expiration behavior
func ttlExpirationExample() {
    // Create cache with short TTL for demonstration
    shortLivedCache := cache.New(2 * time.Second)

    // Store data that will expire quickly
    shortLivedCache.Set("temp:data", "This will expire soon")
    shortLivedCache.Set("temp:session", map[string]string{
        "user":    "testuser",
        "expires": time.Now().Add(2 * time.Second).String(),
    })

    fmt.Println("=== Immediately after setting values ===")

    // Verify data exists immediately
    if value, found := shortLivedCache.Get("temp:data"); found {
        fmt.Printf("Found temp data: %s\n", value.(string))
    }

    if session, found := shortLivedCache.Get("temp:session"); found {
        sessionData := session.(map[string]string)
        fmt.Printf("Found session for user: %s\n", sessionData["user"])
    }

    // Wait for data to expire
    fmt.Println("\n=== Waiting 3 seconds for TTL expiration ===")
    time.Sleep(3 * time.Second)

    // Try to access expired data
    if _, found := shortLivedCache.Get("temp:data"); !found {
        fmt.Println("temp:data has expired (not found)")
    }

    if _, found := shortLivedCache.Get("temp:session"); !found {
        fmt.Println("temp:session has expired (not found)")
    }

    // Demonstrate that new data can still be stored
    shortLivedCache.Set("new:data", "Fresh data after expiration")
    if value, found := shortLivedCache.Get("new:data"); found {
        fmt.Printf("New data stored successfully: %s\n", value.(string))
    }
}

