        cacheKey := fmt.Sprintf("user:%s", userID)

        // Try cache first (fast path)
        if cached, found := dbCache.Get(cacheKey); found {
            fmt.Printf("Cache HIT for user %s\n", userID)
            return cached.(*User), nil
        }

        // Cache miss - fetch from database (slow path)
        fmt.Printf("Cache MISS for user %s - fetching from database\n", userID)
        user, err := db.GetUser(userID)
        if err != nil {
            return nil, err
        }

        // Store in cache for future requests
        dbCache.Set(cacheKey, user)
        return user, nil
    }

    // Simulate multiple requests for the same user
    for i := 0; i < 5; i++ {
        user, err := getUser("123")
        if err != nil {
            fmt.Printf("Error: %v\n", err)
            continue
        }
        fmt.Printf("Retrieved user: %s (%s)\n", user.Name, user.Email)
        time.Sleep(100 * time.Millisecond)
    }
}

