		sessionCache: cache.New(30 * time.Minute), // Session TTL
	}
}

// getUserHandler demonstrates caching user lookups
func (s *Server) getUserHandler(w http.ResponseWriter, r *http.Request) {
	userID := r.URL.Query().Get("id")
	if userID == "" {
		http.Error(w, "User ID required", http.StatusBadRequest)
		return
	}

	// Check cache first (thread-safe)
	cacheKey := "user:" + userID
	if userData, found := s.userCache.Get(cacheKey); found {
		w.Header().Set("Content-Type", "application/json")
		w.Header().Set("X-Cache", "HIT")
		json.NewEncoder(w).Encode(userData)
		return
	}

	// Cache miss - simulate database lookup
	user := s.fetchUserFromDB(userID)
	if user == nil {
		http.Error(w, "User not found", http.StatusNotFound)
		return
	}

	// Store in cache for future requests (thread-safe)
	s.userCache.Set(cacheKey, user)

	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("X-Cache", "MISS")
	json.NewEncoder(w).Encode(user)
}

// loginHandler demonstrates session caching
func (s *Server) loginHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	username := r.FormValue("username")
	password := r.FormValue("password")

	// Simulate authentication
	if !s.authenticate(username, password) {
		http.Error(w, "Invalid credentials", http.StatusUnauthorized)
		return
	}

	// Create session
	sessionID := generateSessionID()
	sessionData := map[string]interface{}{
		"username":  username,
		"loginTime": time.Now(),
		"userAgent": r.UserAgent(),
	}

	// Store session in cache (thread-safe)
	s.sessionCache.Set("session:"+sessionID, sessionData)

	// Set session cookie
	http.SetCookie(w, &http.Cookie{
		Name:     "session_id",
		Value:    sessionID,
		Path:     "/",
		HttpOnly: true,
		Secure:   false, // Set to true in production with HTTPS
		MaxAge:   1800,  // 30 minutes
	})

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Login successful")
}

// protectedHandler demonstrates session validation using cache
func (s *Server) protectedHandler(w http.ResponseWriter, r *http.Request) {
	// Get session cookie
	cookie, err := r.Cookie("session_id")
	if err != nil {
		http.Error(w, "No session found", http.StatusUnauthorized)
		return
	}

	// Validate session (thread-safe cache lookup)
	sessionKey := "session:" + cookie.Value
	sessionData, found := s.sessionCache.Get(sessionKey)
	if !found {
		http.Error(w, "Session expired", http.StatusUnauthorized)
		return
	}

	// Session is valid
	w.Header().Set("Content-Type", "application/json")
	response := map[string]interface{}{
		"message": "Access granted to protected resource",
		"session": sessionData,
	}
	json.NewEncoder(w).Encode(response)
}

// logoutHandler demonstrates session removal
func (s *Server) logoutHandler(w http.ResponseWriter, r *http.Request) {
	cookie, err := r.Cookie("session_id")
	if err != nil {
		http.Error(w, "No session to logout", http.StatusBadRequest)
		return
	}

	// Remove session from cache (thread-safe)
	s.sessionCache.Delete("session:" + cookie.Value)

	// Clear session cookie
	http.SetCookie(w, &http.Cookie{
		Name:     "session_id",
		Value:    "",
		Path:     "/",
		HttpOnly: true,
		MaxAge:   -1, // Expire immediately
	})

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Logout successful")
}

