## Background Worker Example

```go
package main

import (
	"context"
	"fmt"
	"log"
	"sync"
	"time"

	"github.com/example/cache"
)

// MetricsCollector demonstrates cache usage in background workers
type MetricsCollector struct {
	cache    *cache.Cache
	mu       sync.RWMutex
	shutdown chan struct{}
}

// NewMetricsCollector creates a metrics collector with cache
func NewMetricsCollector() *MetricsCollector {
	return &MetricsCollector{
		cache:    cache.New(5 * time.Minute), // 5-minute TTL for metrics
		shutdown: make(chan struct{}),
	}
}

// Start begins the metrics collection process
func (mc *MetricsCollector) Start(ctx context.Context) {
	var wg sync.WaitGroup

	// Start multiple background workers
	wg.Add(3)

	// System metrics worker
	go func() {
		defer wg.Done()
		mc.collectSystemMetrics(ctx)
	}()

	// Application metrics worker  
	go func() {
		defer wg.Done()
		mc.collectAppMetrics(ctx)
	}()

	// Cleanup worker
	go func() {
		defer wg.Done()
		mc.cleanupExpiredMetrics(ctx)
	}()

	// Wait for shutdown signal
	<-ctx.Done()
	close(mc.shutdown)
	wg.Wait()
}

// collectSystemMetrics simulates system metric collection
func (mc *MetricsCollector) collectSystemMetrics(ctx context.Context) {
	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-mc.shutdown:
			return
		case <-ticker.C:
			// Simulate collecting system metrics
			metrics := map[string]interface{}{
				"cpu_usage":    42.5,
				"memory_usage": 68.2,
				"disk_usage":   23.1,
				"timestamp":    time.Now(),
			}

			// Store in cache (thread-safe)
			mc.cache.Set("metrics:system", metrics)
			fmt.Println("System metrics collected and cached")
		}
	}
}

// collectAppMetrics simulates application metric collection
func (mc *MetricsCollector) collectAppMetrics(ctx context.Context) {
	ticker := time.NewTicker(45 * time.Second)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-mc.shutdown:
			return
		case <-ticker.C:
			// Simulate collecting application metrics
			metrics := map[string]interface{}{
				"requests_per_sec": 125.3,
				"error_rate":       0.02,
				"response_time":    45.6,
				"active_users":     1247,
				"timestamp":        time.Now(),
			}

			// Store in cache (thread-safe)
			mc.cache.Set("metrics:application", metrics)
			fmt.Println("Application metrics collected and cached")
		}
	}
}

// cleanupExpiredMetrics demonstrates manual cleanup
func (mc *MetricsCollector) cleanupExpiredMetrics(ctx context.Context) {
	ticker := time.NewTicker(2 * time.Minute)
	defer ticker.Stop()

	for {
		select {
		case <-ctx.Done():
			return
		case <-mc.shutdown:
			return
		case <-ticker.C:
			// In this example, we don't need manual cleanup since
			// the cache handles TTL automatically, but this demonstrates
			// how you could implement custom cleanup logic
			fmt.Println("Cleanup cycle completed (TTL handled automatically)")
		}
	}
}

// GetMetrics retrieves cached metrics (thread-safe)
func (mc *MetricsCollector) GetMetrics(metricType string) (interface{}, bool) {
	return mc.cache.Get("metrics:" + metricType)
}

// GetAllMetrics retrieves all available metrics
func (mc *MetricsCollector) GetAllMetrics() map[string]interface{} {
	result := make(map[string]interface{})

	// Retrieve all known metric types (thread-safe)
	metricTypes := []string{"system", "application"}

	for _, metricType := range metricTypes {
		if metrics, found := mc.cache.Get("metrics:" + metricType); found {
			result[metricType] = metrics
		}
	}

	return result
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	collector := NewMetricsCollector()

	// Start metrics collection in background
	go collector.Start(ctx)

	// Simulate metrics retrieval from multiple goroutines
	var wg sync.WaitGroup

	// Reader goroutines
	for i := 0; i < 3; i++ {
		wg.Add(1)
		go func(readerID int) {
			defer wg.Done()

			for j := 0; j < 10; j++ {
				time.Sleep(15 * time.Second)

				// Read system metrics (thread-safe)
				if metrics, found := collector.GetMetrics("system"); found {
					fmt.Printf("Reader %d: System metrics: %v\n", readerID, metrics)
				}

				// Read application metrics (thread-safe)
				if metrics, found := collector.GetMetrics("application"); found {
					fmt.Printf("Reader %d: App metrics: %v\n", readerID, metrics)
				}

				// Get all metrics
				allMetrics := collector.GetAllMetrics()
				fmt.Printf("Reader %d: Total metric types available: %d\n", 
					readerID, len(allMetrics))
			}
		}(i)
	}

	// Run for demonstration period
	time.Sleep(3 * time.Minute)

	// Shutdown
	fmt.Println("Shutting down...")
	cancel()
	wg.Wait()

	fmt.Println("All workers stopped")
}
