var cache = cache.New(5 * time.Minute)

// Concurrent reads from multiple workers
for i := 0; i < 100; i++ {
    go func(id int) {
        if data, exists := cache.Get(fmt.Sprintf("key:%d", id)); exists {
            processData(data)
        }
    }(i)
}

// Concurrent writes from different sources
