## TTL Expiration Example

```go
package main

import (
    "fmt"
    "time"
    "your-project/cache"
)

func main() {
    // Create cache with very short TTL for demonstration
    shortCache := cache.New(2 * time.Second)

    fmt.Println("=== TTL Expiration Example ===")

    // Store data
    shortCache.Set("temp:data", "This will expire soon")
    fmt.Println("Stored temporary data")

    // Immediate retrieval - should succeed
    if value, exists := shortCache.Get("temp:data"); exists {
        fmt.Printf("Immediately after storage: %s\n", value)
    }

    // Wait 1 second - should still exist
    time.Sleep(1 * time.Second)
    if value, exists := shortCache.Get("temp:data"); exists {
        fmt.Printf("After 1 second: %s\n", value)
    } else {
        fmt.Println("After 1 second: Data expired")
    }

    // Wait another 2 seconds - should be expired
    time.Sleep(2 * time.Second)
    if value, exists := shortCache.Get("temp:data"); exists {
        fmt.Printf("After 3 seconds total: %s\n", value)
    } else {
        fmt.Println("After 3 seconds total: Data expired")
    }

    fmt.Println("\n=== Different TTL Caches ===")

    // Show different TTL configurations
    quickCache := cache.New(1 * time.Second)
    slowCache := cache.New(10 * time.Second)

    quickCache.Set("quick", "expires fast")
    slowCache.Set("slow", "expires slowly")

    time.Sleep(2 * time.Second)

    if _, exists := quickCache.Get("quick"); exists {
        fmt.Println("Quick cache: Still exists")
    } else {
        fmt.Println("Quick cache: Expired")
    }

    if _, exists := slowCache.Get("slow"); exists {
        fmt.Println("Slow cache: Still exists")
    } else {
        fmt.Println("Slow cache: Expired")
    }
}
```

