    // Check for non-existent key
    if _, exists := c.Get("user:bob"); !exists {
        fmt.Println("Bob not in cache")
    }

    // Clean up
    c.Delete("config:timeout")
    c.Purge() // Clear all entries
}
```

### Thread-Safe Concurrent Operations

```go
package main

import (
    "fmt"
    "sync"
    "time"
    "your-project/cache"
)

func main() {
    // Create cache instance - thread-safe for concurrent access
    c := cache.New(5 * time.Minute)

    var wg sync.WaitGroup

    // Concurrent writers - thread-safe Set operations
    for i := 0; i < 10; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            key := fmt.Sprintf("worker:%d", id)
            value := fmt.Sprintf("data-from-worker-%d", id)
            c.Set(key, value) // Thread-safe write
        }(i)
    }

    // Concurrent readers - thread-safe Get operations
    for i := 0; i < 5; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            key := fmt.Sprintf("worker:%d", id)
            if value, exists := c.Get(key); exists { // Thread-safe read
                fmt.Printf("Reader %d found: %s\n", id, value)
            }
        }(i)
    }

    // Mixed operations are thread-safe
    wg.Add(1)
    go func() {
        defer wg.Done()
        time.Sleep(100 * time.Millisecond)
        c.Delete("worker:0") // Thread-safe delete during concurrent access
    }()

    wg.Wait()
    fmt.Println("All concurrent operations completed safely")
}
```

