### Computation Result Caching

```go
package main

import (
    "fmt"
    "math"
    "sync"
    "time"
    "your-project/cache"
)

// Thread-safe cache for expensive computations
var computeCache = cache.New(1 * time.Hour)

// ExpensiveComputation simulates a costly operation
func ExpensiveComputation(input float64) float64 {
    cacheKey := fmt.Sprintf("compute:%.2f", input)

    // Thread-safe cache lookup
    if cached, hit := computeCache.Get(cacheKey); hit {
        fmt.Printf("Cache hit for input %.2f\n", input)
        return cached.(float64)
    }

    fmt.Printf("Computing result for input %.2f...\n", input)
    time.Sleep(2 * time.Second) // Simulate expensive work
    result := math.Pow(input, 3) + math.Sin(input*math.Pi)

    // Thread-safe cache storage
    computeCache.Set(cacheKey, result)
    return result
}

func main() {
    var wg sync.WaitGroup
    inputs := []float64{1.5, 2.0, 1.5, 3.0, 2.0} // Note the duplicates

    // Process computations concurrently - cache operations are thread-safe
    for i, input := range inputs {
        wg.Add(1)
        go func(id int, val float64) {
            defer wg.Done()
            result := ExpensiveComputation(val)
            fmt.Printf("Worker %d: f(%.2f) = %.4f\n", id, val, result)
        }(i, input)
    }

    wg.Wait()

    // Demonstrate cache cleanup
    fmt.Println("\nCleaning up cache...")
    computeCache.Purge() // Thread-safe cache clear
    fmt.Println("Cache cleared")
}
