# Extracted Function Implementations

## 1. Input Validation Implementation

```typescript
class EmailRequestValidator implements RequestValidator {
  validate(request: unknown): ValidationResult {
    const errors: ValidationError[] = [];

    // Input validation
    if (!request || typeof request !== 'object') {
      return {
        isValid: false,
        errors: [{ field: 'request', message: 'Invalid request format', code: 'INVALID_FORMAT' }]
      };
    }

    const data = request as Record<string, unknown>;

    // Validate name
    if (!data.name || typeof data.name !== 'string' || data.name.trim().length === 0) {
      errors.push({ field: 'name', message: 'Name is required', code: 'REQUIRED' });
    }

    // Validate email
    if (!data.email || typeof data.email !== 'string') {
      errors.push({ field: 'email', message: 'Email is required', code: 'REQUIRED' });
    } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(data.email)) {
      errors.push({ field: 'email', message: 'Invalid email format', code: 'INVALID_FORMAT' });
    }

    // Validate age
    if (data.age === undefined || data.age === null) {
      errors.push({ field: 'age', message: 'Age is required', code: 'REQUIRED' });
    } else if (typeof data.age !== 'number' || data.age < 0 || data.age > 150) {
      errors.push({ field: 'age', message: 'Age must be between 0 and 150', code: 'INVALID_RANGE' });
    }

    if (errors.length > 0) {
      return { isValid: false, errors };
    }

    return {
      isValid: true,
      errors: [],
      validatedData: {
        name: (data.name as string).trim(),
        email: (data.email as string).toLowerCase(),
        age: data.age as number
      }
    };
  }
}
```

## 2. Data Normalization Implementation

```typescript
class UserDataNormalizer implements DataNormalizer {
  normalize(validatedData: ValidatedRequest): NormalizedData {
    // Input validation
    if (!validatedData) {
      throw new Error('Validated data is required');
    }

    if (!validatedData.name || !validatedData.email || validatedData.age === undefined) {
      throw new Error('Invalid validated data structure');
    }

    return {
      name: validatedData.name.trim().replace(/\s+/g, ' '),
      email: validatedData.email.toLowerCase().trim(),
      age: Math.floor(validatedData.age)
    };
  }
}
