## 3. Data Persistence Implementation

```typescript
class DatabaseUserRepository implements UserRepository {
  private users: Map<string, User> = new Map();

  async findByEmail(email: string): Promise<User | null> {
    // Input validation
    if (!email || typeof email !== 'string') {
      throw new Error('Valid email is required');
    }

    const normalizedEmail = email.toLowerCase().trim();
    for (const user of this.users.values()) {
      if (user.email === normalizedEmail) {
        return user;
      }
    }
    return null;
  }

  async create(userData: NormalizedData): Promise<User> {
    // Input validation
    if (!userData || !userData.name || !userData.email || userData.age === undefined) {
      throw new Error('Valid user data is required');
    }

    const user: User = {
      id: `user_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      name: userData.name,
      email: userData.email,
      age: userData.age,
      createdAt: new Date(),
      updatedAt: new Date()
    };

    this.users.set(user.id, user);
    return user;
  }

  async update(user: User, data: Partial<NormalizedData>): Promise<User> {
    // Input validation
    if (!user || !user.id) {
      throw new Error('Valid user is required');
    }

    if (!data || Object.keys(data).length === 0) {
      throw new Error('Update data is required');
    }

    const existingUser = this.users.get(user.id);
    if (!existingUser) {
      throw new Error('User not found');
    }

    const updatedUser: User = {
      ...existingUser,
      ...data,
      updatedAt: new Date()
    };

    this.users.set(user.id, updatedUser);
    return updatedUser;
  }

  async save(user: User): Promise<void> {
    // Input validation
    if (!user || !user.id) {
      throw new Error('Valid user with ID is required');
    }

    this.users.set(user.id, { ...user, updatedAt: new Date() });
  }
}
```

