## 5. Clean Request Handler Implementation

```typescript
class UserRequestHandler implements RequestHandler {
  constructor(
    private validator: RequestValidator,
    private normalizer: DataNormalizer,
    private repository: UserRepository,
    private notificationService: NotificationService
  ) {
    // Input validation
    if (!validator || !normalizer || !repository || !notificationService) {
      throw new Error('All dependencies are required');
    }
  }

  async handleRequest(request: unknown): Promise<HandleResult> {
    try {
      // Validate input
      const validationResult = this.validator.validate(request);
      if (!validationResult.isValid) {
        return {
          success: false,
          error: validationResult.errors.map(e => e.message).join(', '),
          statusCode: 400
        };
      }

      // Normalize data
      const normalizedData = this.normalizer.normalize(validationResult.validatedData!);

      // Check existing user
      const existingUser = await this.repository.findByEmail(normalizedData.email);
      let user: User;

      if (existingUser) {
        user = await this.repository.update(existingUser, normalizedData);
      } else {
        user = await this.repository.create(normalizedData);
        await this.notificationService.sendWelcomeEmail(user);
      }

      // Record analytics
      await this.notificationService.recordAnalyticsEvent({
        type: existingUser ? 'user_updated' : 'user_created',
        userId: user.id,
        timestamp: new Date(),
        metadata: { email: user.email }
      });

      return {
        success: true,
        data: user,
        statusCode: existingUser ? 200 : 201
      };

    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Internal server error',
        statusCode: 500
      };
    }
  }
}
```

Each implementation validates its inputs, maintains single responsibility, and avoids god function anti-patterns.

# Pipeline Composition

Here's the refactored `handleRequest` that composes the extracted functions into a clean pipeline:

```typescript
class UserRequestHandler implements RequestHandler {
  constructor(
    private validator: RequestValidator,
    private normalizer: DataNormalizer,
    private repository: UserRepository,
    private notificationService: NotificationService
  ) {
    if (!validator || !normalizer || !repository || !notificationService) {
      throw new Error('All dependencies are required');
    }
  }

  async handleRequest(request: unknown): Promise<HandleResult> {
    try {
      // Step 1: Validate input
      const validationResult = this.validateInput(request);
      if (!validationResult.isValid) {
        return this.createErrorResponse(validationResult.errors, 400);
      }

      // Step 2: Normalize data
      const normalizedData = this.normalizeData(validationResult.validatedData!);

      // Step 3: Process user (create or update)
      const { user, isNewUser } = await this.processUser(normalizedData);

      // Step 4: Send notifications
      await this.handleNotifications(user, isNewUser);

      // Step 5: Return success response
      return this.createSuccessResponse(user, isNewUser);

    } catch (error) {
      return this.createErrorResponse([error], 500);
    }
  }

  private validateInput(request: unknown): ValidationResult {
    return this.validator.validate(request);
  }

  private normalizeData(validatedData: ValidatedRequest): NormalizedData {
    return this.normalizer.normalize(validatedData);
  }

  private async processUser(normalizedData: NormalizedData): Promise<{ user: User; isNewUser: boolean }> {
    const existingUser = await this.repository.findByEmail(normalizedData.email);

    if (existingUser) {
      const updatedUser = await this.repository.update(existingUser, normalizedData);
      return { user: updatedUser, isNewUser: false };
    }

    const newUser = await this.repository.create(normalizedData);
    return { user: newUser, isNewUser: true };
  }

  private async handleNotifications(user: User, isNewUser: boolean): Promise<void> {
    if (isNewUser) {
      await this.notificationService.sendWelcomeEmail(user);
    }

    await this.notificationService.recordAnalyticsEvent({
      type: isNewUser ? 'user_created' : 'user_updated',
      userId: user.id,
      timestamp: new Date(),
      metadata: { email: user.email }
    });
  }

  private createErrorResponse(errors: any[], statusCode: number): HandleResult {
    const errorMessage = Array.isArray(errors) 
      ? errors.map(e => typeof e === 'object' ? e.message : String(e)).join(', ')
      : String(errors);

    return {
      success: false,
      error: errorMessage,
      statusCode
    };
  }

  private createSuccessResponse(user: User, isNewUser: boolean): HandleResult {
    return {
      success: true,
      data: user,
      statusCode: isNewUser ? 201 : 200
    };
  }
}
```

## Pipeline Benefits

✅ **Validate**: Each step validates its inputs and maintains data integrity  
✅ **Interface**: All dependencies use clean interfaces with single responsibilities  
✅ **!God Function**: Main `handleRequest` is now a simple orchestrator, with each step extracted to focused private methods

The pipeline clearly shows the flow: validate → normalize → process → notify → respond, making the code readable and maintainable.
